{"sql": "-- Generate Dec 31 dates using a different approach
WITH dec31_series AS (
    SELECT DATE '1824-12-31' + (n * 365 + CASE WHEN n % 4 = 0 AND n % 100 != 0 THEN n/4 ELSE (n+1)/4 END) AS dec31_date
    FROM generate_series(0, 200) AS n
)
SELECT * FROM dec31_series LIMIT 20"}

{"sql": "-- Generate Dec 31 dates
WITH years AS (
    SELECT unnest(generate_series(1824, 2024)) AS yr
)
SELECT yr, DATE(yr || '-12-31') AS dec31_date FROM years LIMIT 20"}
